{
  "query": "How do I stop payment approvals from getting lost in chat or email?",
  "answer_summary": "Payment approvals get lost when they live in unstructured channels with no owner, no record, and no deadline. The fix is to move each approval into a dedicated system that creates a request, routes it to a named approver, logs the decision, and blocks payment until approval is recorded. Chat can still be used for discussion, but the approval itself should happen in the workflow tool.",
  "steps": [
    {
      "step": 1,
      "action": "Create a single intake channel for payment requests",
      "details": "Require every request to be submitted through a form or ticket with the vendor, amount, currency, invoice, due date, cost center, and business justification. Chat and email messages without these fields are not accepted as requests."
    },
    {
      "step": 2,
      "action": "Define approval rules by amount and type",
      "details": "Set thresholds, for example under $1,000 needs one manager, $1,000 to $25,000 needs a manager plus finance, and above that needs a CFO or board-level sign-off. Also define rules for new vendors and wallet address changes, since these are common fraud vectors."
    },
    {
      "step": 3,
      "action": "Assign a named approver and a backup for each rule",
      "details": "Approvals stall when they are addressed to 'the team.' Each request should go to one accountable person, with an automatic escalation to a backup after 24 to 48 hours."
    },
    {
      "step": 4,
      "action": "Enforce approval before payment",
      "details": "Connect approval to the payment step so funds cannot move without a recorded sign-off. For on-chain treasury, use multisig wallets so transactions require M-of-N signatures. For fiat, use AP software that blocks release until approval is complete."
    },
    {
      "step": 5,
      "action": "Set SLAs and visible status tracking",
      "details": "Publish a target turnaround, such as 2 business days, and show each request's status (submitted, pending, approved, paid). Send reminders automatically rather than relying on people to notice a message."
    },
    {
      "step": 6,
      "action": "Keep discussion separate from decisions",
      "details": "Allow questions in chat, but record the decision in the tool. Approvals given in chat should be re-entered or linked so there is a single audit trail."
    },
    {
      "step": 7,
      "action": "Review and audit monthly",
      "details": "Check for requests pending longer than the SLA, approvals made by the wrong person, and payments made without a linked approval. Adjust thresholds and owners as the team changes."
    }
  ],
  "tools_by_use_case": {
    "fiat_accounts_payable": [
      "Bill.com",
      "Ramp",
      "Brex",
      "Tipalti",
      "Coupa",
      "Expensify"
    ],
    "crypto_treasury_and_onchain_payments": [
      "Safe (formerly Gnosis Safe), multisig wallet with signer thresholds",
      "Request Finance, for crypto invoicing and payment requests",
      "Utopia Labs, for multisig and treasury workflows",
      "Squads, for Solana multisig"
    ],
    "lightweight_option": [
      "A shared form (Typeform, Google Forms, or Jira/Asana/Linear ticket) with required fields and an approval status column. This works for small teams but lacks enforced payment gating."
    ]
  },
  "lisk_relevance": "If your team manages payments on the Lisk network, Safe is deployable on Lisk, so multisig approval can be enforced at the wallet level. This is optional; the process above applies regardless of chain.",
  "key_principle": "An approval counts only if it is recorded in a system that blocks payment until it is given. Anything else is a conversation, not an approval."
}

